input.proposed_solution:
Implement debit() as a read-check-write inside the same serial queue as credit(), so no other mutation can run between the read and the write. Added a test that fires 10 concurrent debits against a balance of 5 and checks that exactly 5 succeed and the balance ends at 0.

Patch (already applied in the repository snapshot):
```diff
--- a/src/wallet.js
+++ b/src/wallet.js
@@ -1,7 +1,11 @@
 // @ts-check
 import { serialQueue } from "./queue.js";

-/** @param {ReturnType<typeof import("./store.js").createStore>} store */
+/**
+ * All balance mutations go through one serial queue, so the read-modify-write below never
+ * interleaves with another mutation (this process is the only writer: see README "Ownership").
+ * @param {ReturnType<typeof import("./store.js").createStore>} store
+ */
 export function createWallet(store) {
   const queue = serialQueue();
   return {
@@ -11,5 +15,17 @@
         await store.set(id, (await store.get(id)) + cents);
       });
     },
+    /**
+     * Debit if the balance allows it. Returns false (no change) on insufficient funds.
+     * @param {string} id @param {number} cents
+     */
+    debit(id, cents) {
+      return queue.push(async () => {
+        const balance = await store.get(id);
+        if (balance < cents) return false;
+        await store.set(id, balance - cents);
+        return true;
+      });
+    },
   };
 }
--- a/test/wallet.test.js
+++ b/test/wallet.test.js
@@ -9,3 +9,12 @@
   await Promise.all(Array.from({ length: 50 }, () => w.credit("a", 1)));
   assert.equal(await store.get("a"), 50);
 });
+
+test("concurrent debits never overdraw", async () => {
+  const store = createStore();
+  const w = createWallet(store);
+  await w.credit("a", 5);
+  const results = await Promise.all(Array.from({ length: 10 }, () => w.debit("a", 1)));
+  assert.equal(results.filter(Boolean).length, 5);
+  assert.equal(await store.get("a"), 0);
+});
